private let phosphorViewBox: Double = 256
private let phosphorStroke: Double = 0
private let chromeViewBox: Double = 24
private let chromeStroke: Double = 2

private func phosphorArt(_ paths: [String]) -> CrowbarIconArt {
  CrowbarIconArt(viewBox: phosphorViewBox, stroke: phosphorStroke, paths: paths)
}

private func chromeArt(_ paths: [String]) -> CrowbarIconArt {
  CrowbarIconArt(viewBox: chromeViewBox, stroke: chromeStroke, paths: paths)
}

